(() => {
  const root = document.documentElement;
  const body = document.body;
  const key = 'jay-reader-preferences';
  const defaults = { dark: false, contrast: false, size: 100, language: 'en' };
  let settings = { ...defaults };
  try { const stored = JSON.parse(localStorage.getItem(key) || '{}'); settings = {dark: stored.dark === true, contrast: stored.contrast === true, size: [100,115,130,150].includes(stored.size) ? stored.size : 100, language: stored.language === 'fr' ? 'fr' : 'en'}; } catch {}
  const script = document.currentScript;
  let dictionary = {};
  let resizeTimer;
  const normalize = text => text.replace(/\s+/g, ' ').trim();
  const nodes = [];
  const walker = document.createTreeWalker(document.documentElement, NodeFilter.SHOW_TEXT, {acceptNode(n) {return n.parentElement?.closest('script,style,noscript,[data-no-translate]') || !normalize(n.nodeValue) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;}});
  while(walker.nextNode()) nodes.push({node: walker.currentNode, original: walker.currentNode.nodeValue});
  const attrs = [];
  document.querySelectorAll('[aria-label],[placeholder],[alt],meta[name=description]').forEach(el => ['aria-label','placeholder','alt','content'].forEach(attr => {if(el.hasAttribute(attr))attrs.push({el,attr,original:el.getAttribute(attr)});}));
  const header = document.querySelector('.site-header');
  const art = header?.querySelector('.art-direction-link');
  const language = document.createElement('div'); language.className='language-switch'; language.dataset.noTranslate=''; language.setAttribute('role','group'); language.setAttribute('aria-label','Language');
  language.innerHTML='<button type="button" data-language="en" lang="en" aria-label="English">ENG</button><span aria-hidden="true">/</span><button type="button" data-language="fr" lang="fr" aria-label="Français">FR</button>';
  if(art){const utilities=document.createElement('div');utilities.className='header-utilities';art.before(utilities);utilities.append(language,art);}else header?.querySelector('.header-actions')?.before(language);
  const toggle = document.createElement('button'); toggle.type='button';toggle.className='preferences-toggle';toggle.dataset.noTranslate='';toggle.setAttribute('aria-controls','reader-panel');toggle.setAttribute('aria-haspopup','dialog');toggle.setAttribute('aria-expanded','false');toggle.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="4.5" r="2"/><path d="M4.5 9.5 12 11l7.5-1.5M12 11v5m0 0-4.5 5M12 16l4.5 5"/></svg>';
  const panel=document.createElement('dialog');panel.id='reader-panel';panel.className='preferences-panel';panel.dataset.noTranslate='';panel.setAttribute('aria-labelledby','reader-title');
  panel.innerHTML='<div class="preferences-panel__head"><h2 id="reader-title"></h2><button type="button" class="preferences-close">×</button></div><div class="preference-row"><label for="reader-dark"><span data-copy="dark"></span><input type="checkbox" id="reader-dark"></label></div><div class="preference-row"><label for="reader-contrast"><span data-copy="contrast"></span><input type="checkbox" id="reader-contrast"></label></div><div class="preference-row"><span id="reader-size-label" data-copy="size"></span><div class="text-size-controls" role="group" aria-labelledby="reader-size-label"><button type="button" data-size="less">A−</button><output aria-live="polite"></output><button type="button" data-size="more">A+</button></div></div><button type="button" class="preferences-reset"></button>';
  body.append(toggle,panel);
  const copy={en:{title:'Reading settings',dark:'Dark mode',contrast:'Higher contrast',size:'Text size',reset:'Reset settings',open:'Reading settings',close:'Close settings',less:'Decrease text size',more:'Increase text size',updated:'Language changed to English'},fr:{title:'Options de lecture',dark:'Mode sombre',contrast:'Contraste renforcé',size:'Taille du texte',reset:'Réinitialiser',open:'Options de lecture',close:'Fermer les options',less:'Réduire le texte',more:'Agrandir le texte',updated:'Langue changée en français'}};
  const announce=document.createElement('span');announce.className='sr-only';announce.setAttribute('role','status');announce.dataset.noTranslate='';body.append(announce);
  const targets=[...document.querySelectorAll('h1,h2,h3,h4,h5,h6,p,li,figcaption,label,input,textarea,button,a,th,td')].filter(n=>!n.closest('.site-header,.mobile-menu,.preferences-panel,.preferences-toggle,.case-index,.work-panel,.loader') && !(n.matches('a')&&n.querySelector('h1,h2,h3,h4')));
  function measure(){body.classList.remove('reader-sized');targets.forEach(n=>{n.style.setProperty('--reader-size',getComputedStyle(n).fontSize);n.dataset.readerText='';});body.classList.toggle('reader-sized',settings.size!==100);}
  function save(){try{localStorage.setItem(key,JSON.stringify(settings));}catch{}}
  function apply(){body.classList.toggle('reader-dark',settings.dark);body.classList.toggle('reader-contrast',settings.contrast);body.classList.toggle('reader-sized',settings.size!==100);body.style.setProperty('--reader-scale',settings.size/100);panel.querySelector('#reader-dark').checked=settings.dark;panel.querySelector('#reader-contrast').checked=settings.contrast;panel.querySelector('output').textContent=settings.size+'%';panel.querySelector('[data-size=less]').disabled=settings.size===100;panel.querySelector('[data-size=more]').disabled=settings.size===150;const c=copy[settings.language];toggle.setAttribute('aria-label',c.open);panel.querySelector('h2').textContent=c.title;panel.querySelector('.preferences-close').setAttribute('aria-label',c.close);panel.querySelector('.preferences-reset').textContent=c.reset;panel.querySelector('[data-size=less]').setAttribute('aria-label',c.less);panel.querySelector('[data-size=more]').setAttribute('aria-label',c.more);panel.querySelectorAll('[data-copy]').forEach(n=>n.textContent=c[n.dataset.copy]);language.querySelectorAll('button').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.language===settings.language)));requestAnimationFrame(()=>{window.ScrollTrigger?.refresh();window.dispatchEvent(new Event('resize'));});save();}
  function translate(){root.lang=settings.language;nodes.forEach(({node,original})=>{const value=dictionary[normalize(original)];node.nodeValue=settings.language==='fr'&&value?original.replace(/\S[\s\S]*\S|\S/,value):original;});attrs.forEach(({el,attr,original})=>{let value=dictionary[normalize(original)];if(!value&&attr==='aria-label'&&original.startsWith('Enlarge: '))value='Agrandir : '+(dictionary[original.slice(9)]||original.slice(9));el.setAttribute(attr,settings.language==='fr'&&value?value:original);});apply();}
  toggle.addEventListener('click',()=>{panel.showModal();toggle.setAttribute('aria-expanded','true');panel.querySelector('.preferences-close').focus();});
  const close=()=>panel.close();panel.querySelector('.preferences-close').addEventListener('click',close);panel.addEventListener('close',()=>{toggle.setAttribute('aria-expanded','false');toggle.focus();});panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
  panel.querySelector('#reader-dark').addEventListener('change',e=>{settings.dark=e.target.checked;apply();});panel.querySelector('#reader-contrast').addEventListener('change',e=>{settings.contrast=e.target.checked;apply();});
  panel.querySelectorAll('[data-size]').forEach(n=>n.addEventListener('click',()=>{const sizes=[100,115,130,150];settings.size=sizes[sizes.indexOf(settings.size)+(n.dataset.size==='more'?1:-1)];apply();}));
  panel.querySelector('.preferences-reset').addEventListener('click',()=>{settings={...defaults};translate();});
  language.querySelectorAll('button').forEach(n=>n.addEventListener('click',()=>{settings.language=n.dataset.language;translate();announce.textContent=copy[settings.language].updated;}));
  const tooltip = document.createElement('div');
  tooltip.id='action-tooltip';tooltip.className='action-tooltip';tooltip.setAttribute('role','tooltip');tooltip.dataset.noTranslate='';tooltip.hidden=true;body.append(tooltip);
  const tooltipCopy={en:{home:'Go back home',work:'Explore selected projects',art:'Visit my art direction studio',settings:'Accessibility and reading settings',contact:'Get in touch'},fr:{home:'Retour à l’accueil',work:'Découvrir les projets',art:'Visiter mon studio de direction artistique',settings:'Accessibilité et options de lecture',contact:'Me contacter'}};
  const tooltipTargets=new Map();
  const addTips=(selector,type)=>document.querySelectorAll(selector).forEach(n=>tooltipTargets.set(n,type));
  addTips('.site-header .wordmark','home');addTips('.clean-hero__cta','work');addTips('.art-direction-link','art');addTips('.preferences-toggle','settings');addTips('.contact-v2 > a,.site-footer a[href^="mailto:"],a[href="contact.html"],a[href="../contact.html"]','contact');
  let activeTip=null,tipTimer,tipDismissed=false;
  function positionTip(){if(!activeTip)return;const r=activeTip.getBoundingClientRect(),w=tooltip.offsetWidth,h=tooltip.offsetHeight;tooltip.style.left=Math.max(12,Math.min(innerWidth-w-12,r.left+(r.width-w)/2))+'px';tooltip.style.top=(r.bottom+h+12<innerHeight?r.bottom+8:Math.max(8,r.top-h-8))+'px';}
  function hideTip(){clearTimeout(tipTimer);tooltip.hidden=true;if(activeTip){const description=(activeTip.getAttribute('aria-describedby')||'').split(/\s+/).filter(v=>v&&v!==tooltip.id).join(' ');if(description)activeTip.setAttribute('aria-describedby',description);else activeTip.removeAttribute('aria-describedby');}activeTip=null;}
  function showTip(n){if(tipDismissed||panel.open)return;hideTip();activeTip=n;tooltip.textContent=tooltipCopy[settings.language][tooltipTargets.get(n)];tooltip.hidden=false;n.setAttribute('aria-describedby',[(n.getAttribute('aria-describedby')||''),tooltip.id].filter(Boolean).join(' '));positionTip();}
  tooltipTargets.forEach((type,n)=>{n.addEventListener('pointerenter',()=>{tipDismissed=false;clearTimeout(tipTimer);tipTimer=setTimeout(()=>showTip(n),220);});n.addEventListener('pointerleave',()=>{clearTimeout(tipTimer);tipTimer=setTimeout(hideTip,100);});n.addEventListener('focus',()=>{tipDismissed=false;showTip(n);});n.addEventListener('blur',hideTip);n.addEventListener('click',hideTip);});
  tooltip.addEventListener('pointerenter',()=>clearTimeout(tipTimer));tooltip.addEventListener('pointerleave',hideTip);
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){tipDismissed=true;hideTip();}});document.addEventListener('scroll',hideTip,{passive:true});window.addEventListener('resize',positionTip);
  measure();apply();document.fonts.ready.then(measure);window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(measure,120);});
  fetch(new URL('translations-fr.json',script.src)).then(r=>{if(!r.ok)throw Error('Translation unavailable');return r.json();}).then(data=>{dictionary=data;translate();}).catch(()=>{settings.language='en';translate();});
})();
